/* =====================================================================
 * AI Car Racing - 200 levels in 8 chapters of 25.
 *
 * The table is generated by a deterministic formula that MUST mirror
 * com.typemaster.arena.config.DataInitializer (the server copy is loaded
 * from /api/racing/levels and replaces this one when available).
 *
 *  AI speed : level 1 = 1 m/s, 2 = 2 m/s, 3 = 3 m/s, then a smooth curve
 *             up to 12 m/s at level 200 (~125 WPM needed).
 *  Distance : 90 m at level 1 growing to 400 m at level 200.
 *  Penalty  : 0 m (levels 1-2) growing to 3 m per mistake.
 *  Certificate: winning level 50 earns the TypeMaster Arena certificate.
 * ===================================================================== */
window.TM = window.TM || {};

(function (TM) {
  'use strict';

  const TOTAL = 200;
  const CERT_LEVEL = 50;

  const CHAPTERS = [
    { name: 'Rookie Circuit', theme: 'DAY', base: 'EASY', alt: 'EASY', final: 'Rookie Cup Final',
      tracks: ['Rookie Rally', 'Neighbourhood Dash', 'Park Loop', 'School Run', 'Village Sprint'] },
    { name: 'City Grand Prix', theme: 'NIGHT', base: 'EASY', alt: 'MEDIUM', final: 'Certification Grand Prix',
      tracks: ['Downtown Dash', 'City Lights', 'Harbour Bridge', 'Metro Mile', 'Skyline Sprint'] },
    { name: 'Desert Rally', theme: 'DESERT', base: 'MEDIUM', alt: 'MEDIUM', final: 'Desert King Final',
      tracks: ['Dune Runner', 'Canyon Run', 'Mirage Mile', 'Oasis Loop', 'Sandstorm Sprint'] },
    { name: 'Frozen Peaks', theme: 'SNOW', base: 'MEDIUM', alt: 'HARD', final: 'Century Cup',
      tracks: ['Frozen Track', 'Blizzard Bend', 'Glacier Gap', 'Avalanche Alley', 'Polar Pass'] },
    { name: 'Neon Nights', theme: 'NEON', base: 'HARD', alt: 'HARD', final: 'Neon Crown Final',
      tracks: ['Neon Boulevard', 'Synthwave Strip', 'Laser Lane', 'Pixel Parkway', 'Cyber Circuit'] },
    { name: 'Coastal Highway', theme: 'SUNSET', base: 'HARD', alt: 'MIXED', final: 'Coastal Championship',
      tracks: ['Sunset Sprint', 'Ocean Drive', 'Palm Avenue', 'Lighthouse Loop', 'Tidal Turn'] },
    { name: 'Mountain Pass', theme: 'DAY', base: 'EXPERT', alt: 'MIXED', final: 'Mountain Master Final',
      tracks: ['Eagle Ridge', 'Thunder Pass', 'Summit Climb', 'Pine Valley', 'Cliffside Curve'] },
    { name: 'Legends League', theme: 'NEON', base: 'EXPERT', alt: 'EXPERT', final: 'TypeMaster Grand Final',
      tracks: ["Champion's Circuit", 'Titan Track', 'Legend Loop', 'Hall of Fame Highway', 'Grand Master Mile'] }
  ];
  const SPECIAL_POOLS = ['CAPITALS', 'PUNCTUATION', 'NUMBERS', 'MIXED'];
  const ROMAN = ['I', 'II', 'III', 'IV', 'V'];
  const POOL_DESC = {
    EASY: 'Short, easy words.',
    MEDIUM: 'Everyday medium-length words.',
    HARD: 'Long, difficult words.',
    EXPERT: 'Expert vocabulary with tricky spellings.',
    CAPITALS: 'Capitalised words - master the Shift key.',
    PUNCTUATION: 'Words with commas, periods and quotes.',
    NUMBERS: 'Digits and numeric codes.',
    MIXED: 'A mix of everything.'
  };

  const round1 = (v) => Math.round(v * 10) / 10;
  const num = (v) => String(v); // 3 -> "3", 3.5 -> "3.5" (matches the server text)

  /** AI speed (m/s). */
  const aiSpeedFor = (n) => (n <= 3 ? n : round1(3 + 9 * Math.pow((n - 3) / (TOTAL - 3), 0.8)));
  /** Track length (m), rounded to 10. */
  const distanceFor = (n) => Math.round((90 + 310 * Math.pow((n - 1) / (TOTAL - 1), 0.7)) / 10) * 10;
  /** Metres lost per wrong keystroke. */
  const penaltyFor = (n) => (n <= 2 ? 0 : Math.min(3, Math.round((0.5 + n / 50) * 2) / 2));

  function build(n) {
    const c = Math.floor((n - 1) / 25);
    const s = ((n - 1) % 25) + 1;          // stage inside the chapter (1-25)
    const round = Math.floor((s - 1) / 5); // 0-4
    const ch = CHAPTERS[c];
    const pool = s % 5 === 0 && s !== 25 && n > 5 ? SPECIAL_POOLS[(n / 5) % 4] : (s % 2 === 0 || s === 25 ? ch.alt : ch.base);
    const theme = round === 2 ? (ch.theme === 'NIGHT' ? 'NEON' : 'NIGHT') : ch.theme;
    const name = s === 25 ? ch.final : `${ch.tracks[(s - 1) % 5]} ${ROMAN[round]}`;
    const ai = aiSpeedFor(n), dist = distanceFor(n), pen = penaltyFor(n);
    let challenge = `${POOL_DESC[pool]} AI drives at ${num(ai)} m/s over ${dist} m.`;
    challenge += pen > 0 ? ` Each mistake costs ${num(pen)} m.` : ' No mistake penalty.';
    if (n === CERT_LEVEL) challenge += ' Win to earn your certificate!';
    else if (s === 25) challenge += ' Chapter final!';
    return { level: n, name, wordPool: pool, mistakePenalty: pen, theme, challenge, aiSpeed: ai, distance: dist };
  }

  TM.RACING_LEVELS = Array.from({ length: TOTAL }, (_, i) => build(i + 1));
  TM.RACING_CHAPTERS = CHAPTERS.map((c, i) => ({ index: i, name: c.name, from: i * 25 + 1, to: i * 25 + 25 }));
  TM.RACING_TOTAL = TOTAL;
  TM.CERT_LEVEL = CERT_LEVEL;
  TM.chapterOf = (n) => Math.floor((n - 1) / 25);

  /** Approximate WPM needed to tie the AI (1 m per correct char, ~1.15x average streak bonus). */
  TM.requiredWpm = (lvl) => Math.round((lvl.aiSpeed * 12) / 1.15);
})(window.TM);
